using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorSpatialGizmoOperations:RefCounted
{
    private readonly ActorDefinitionOperations _definitions=new();private readonly Expression _rayBox=new();
    public ActorSpatialGizmoOperations(){_rayBox.Parse("box.intersects_ray(origin,direction)",new[]{"box","origin","direction"});}
    private static readonly string[] Modes={"move","rotate","scale"};private static readonly Color[] Colors3={new Color("f27e81"),new Color("84dc9e"),new Color("80baff")};private static readonly int[][] Edges={new[]{0,1},new[]{0,2},new[]{0,4},new[]{1,3},new[]{1,5},new[]{2,3},new[]{2,6},new[]{3,7},new[]{4,5},new[]{4,6},new[]{5,7},new[]{6,7}};
    private static readonly HashSet<string> Proxies=new(){"point_3d","remote_transform","light_3d","directional_light","skeleton_rig","powder","fog_volume","global_fog"};
    private static Node? Editor(Node owner)=>owner.Get("editor").AsGodotObject() as Node;private static Control Gizmo(Node owner)=>owner.Get("gizmo").As<Control>();private static RefCounted Model(Node owner)=>Editor(owner)!.Get("model").As<RefCounted>();private static GodotObject Module(Node owner,string key)=>owner.Get(key).AsGodotObject();private static string Mode(Node owner)=>owner.Get("mode").AsString();
    private static bool Script(Node? node,string path){var script=node?.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://scripts/actors/"+path+".gd")return true;script=script.GetBaseScript();}return false;}
    private static bool Ui(Node? node)=>Script(node,"examples/ui_actor");private static Resource Actor(Node runtime)=>runtime.Get("actor").As<Resource>();private static Transform3D Remote(Node runtime)=>runtime.Call("remote_transform").AsTransform3D();private static Node3D? Runtime(Node owner,Resource? clip)=>clip!=null?Editor(owner)!.Call("_runtime_for_clip",clip.Get("id")).AsGodotObject() as Node3D:null;
    public void ready(Node owner){foreach(string key in new[]{"rig","physics_pins","damage","structure","fog_paint"})Module(owner,key).Set("spatial",owner);}
    public Camera3D? camera(Node owner){var editor=Editor(owner);if(!GodotObject.IsInstanceValid(editor))return null;var holder=editor!.Get("runtime_holder").AsGodotObject() as Node;return GodotObject.IsInstanceValid(holder)?holder!.GetViewport().GetCamera3D():null;}
    public bool enabled(Node owner){var editor=Editor(owner);return GodotObject.IsInstanceValid(editor)&&!editor!.Get("exporting").AsBool()&&!editor.Get("audio_recorder").AsGodotObject().Get("recording").AsBool()&&!editor.Get("screen_recorder").AsGodotObject().Get("recording").AsBool();}
    public Node3D? primary(Node owner){var runtime=enabled(owner)?Runtime(owner,Model(owner).Call("selected_clip").As<Resource>()):null;if(runtime==null||!runtime.Get("active").AsBool()||Ui(runtime)||!runtime.Call("supports_remote_transform").AsBool())return null;var definition=_definitions.get_definition(Editor(owner)!.Get("registry").As<RefCounted>(),Actor(runtime).Get("type_id").AsStringName());return definition!=null&&_definitions.find_property(definition,new StringName("position"))!=null?runtime:null;}
    public Vector2 project(Node owner,Vector3 point)=>Gizmo(owner).Call("display_transform").AsTransform2D()*camera(owner)!.UnprojectPosition(point);
    public bool in_picture(Node owner,Vector2 point){var holder=Editor(owner)!.Get("runtime_holder").AsGodotObject() as Node;return GodotObject.IsInstanceValid(holder)&&new Rect2(Vector2.Zero,holder!.GetViewport().GetVisibleRect().Size).HasPoint(Gizmo(owner).Call("scene_point",point).AsVector2());}
    public void collect_visuals(Node owner,Node node,GArray result,bool root){if(!root&&Script(node,"core/actor_runtime"))return;if(node is FogVolume fog&&fog.Shape==RenderingServer.FogVolumeShape.World)return;if(node is VisualInstance3D visual&&visual.IsVisibleInTree()&&visual is not Light3D&&(visual.Layers&camera(owner)!.CullMask)!=0)result.Add(visual);foreach(var child in node.GetChildren())collect_visuals(owner,child,result,false);}
    public GArray visuals(Node owner,Node3D? runtime){var result=new GArray();if(runtime!=null&&runtime.Get("active").AsBool()&&camera(owner)!=null)collect_visuals(owner,runtime,result,true);return result;}
    public Settings bounds(Node owner,Node3D? runtime){var result=new Aabb();bool found=false;foreach(var value in visuals(owner,runtime)){var visual=value.As<VisualInstance3D>();var local=visual.GetAabb();if(!local.Position.IsFinite()||!local.Size.IsFinite())continue;var box=visual.GlobalTransform*local;result=found?result.Merge(box):box;found=true;}if(!found&&runtime!=null&&Proxies.Contains(Actor(runtime).Get("type_id").AsString())){var origin=Remote(runtime).Origin;result=new Aabb(origin-Vector3.One*.15f,Vector3.One*.3f);found=true;}return found?new Settings{["box"]=result}:new Settings();}
    public GArray box_lines(Node owner,Node3D runtime){var result=new GArray();var data=bounds(owner,runtime);var lens=camera(owner);if(data.Count==0||lens==null)return result;var box=data["box"].AsAabb();var corners=new Vector3[8];for(int i=0;i<8;i++)corners[i]=box.Position+box.Size*new Vector3(i&1,(i>>1)&1,(i>>2)&1);var inverse=lens.GlobalTransform.AffineInverse();foreach(var edge in Edges){var a=corners[edge[0]];var b=corners[edge[1]];float da=-(inverse*a).Z,db=-(inverse*b).Z,near=lens.Near+.001f;if(da<near&&db<near)continue;if(da<near)a=a.Lerp(b,(near-da)/(db-da));else if(db<near)b=b.Lerp(a,(near-db)/(da-db));result.Add(new[]{project(owner,a),project(owner,b)});}return result;}
    public Settings ray(Node owner,Vector2 point){var position=Gizmo(owner).Call("scene_point",point).AsVector2();var lens=camera(owner)!;return new Settings{["origin"]=lens.ProjectRayOrigin(position),["direction"]=lens.ProjectRayNormal(position)};}
    public Variant hit_visual(VisualInstance3D visual,Settings ray)
    {
        var transform=visual.GlobalTransform;if(Math.Abs(transform.Basis.Determinant())<.0000001)return default;var inverse=transform.AffineInverse();var origin=inverse*ray["origin"].AsVector3();var direction=(inverse.Basis*ray["direction"].AsVector3()).Normalized();var hit=_rayBox.Execute(new GArray{visual.GetAabb(),origin,direction});if(hit.VariantType==Variant.Type.Nil)return default;if(visual is MeshInstance3D instance&&instance.Mesh!=null){var mesh=instance.Mesh;bool triangles=mesh is PrimitiveMesh;int vertices=0;for(int i=0;i<mesh.GetSurfaceCount();i++){if(mesh is ArrayMesh array){if(array.SurfaceGetPrimitiveType(i)==Mesh.PrimitiveType.Triangles)triangles=true;vertices+=array.SurfaceGetArrayLen(i);}else{var arrays=mesh.SurfaceGetArrays(i);if(arrays.Count>(int)Mesh.ArrayType.Vertex&&arrays[(int)Mesh.ArrayType.Vertex].VariantType!=Variant.Type.Nil)vertices+=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array().Length;}}if(triangles&&vertices<=150000){var geometry=mesh.GenerateTriangleMesh();if(geometry!=null){var narrow=geometry.IntersectRay(origin,direction);if(narrow.Count==0)return default;hit=narrow["position"];}}}return transform*hit.AsVector3();
    }
    public string pick(Node owner,Vector2 point)
    {
        var lens=camera(owner);if(!enabled(owner)||lens==null||!in_picture(owner,point))return "";var ray= this.ray(owner,point);float best=float.PositiveInfinity;string chosen="";var origin=ray["origin"].AsVector3();var inverse=lens.GlobalTransform.AffineInverse();foreach(var value in Model(owner).Get("clips").AsGodotArray()){var clip=value.As<Resource>();var runtime=Runtime(owner,clip);if(runtime==null||!runtime.Get("active").AsBool()||Ui(runtime))continue;var owned=visuals(owner,runtime);foreach(var item in owned){var hit=hit_visual(item.As<VisualInstance3D>(),ray);if(hit.VariantType==Variant.Type.Nil)continue;var position=hit.AsVector3();if(lens.IsPositionBehind(position))continue;float depth=-(inverse*position).Z;if(depth<lens.Near||depth>lens.Far)continue;float distance=origin.DistanceTo(position);if(distance<best){best=distance;chosen=clip.Get("id").AsString();}}if(owned.Count==0&&Proxies.Contains(Actor(runtime).Get("type_id").AsString())){var position=Remote(runtime).Origin;if(lens.IsPositionBehind(position))continue;float distance=origin.DistanceTo(position);if(project(owner,position).DistanceTo(point)<12&&distance<best){best=distance;chosen=clip.Get("id").AsString();}}}return chosen;
    }
    public Settings geometry(Node owner)
    {
        var runtime=primary(owner);var lens=camera(owner);if(runtime==null||lens==null)return new Settings();var rig=Module(owner,"rig");bool bones=rig.Call("active").AsBool();var transform=bones?rig.Call("transform").AsTransform3D():Remote(runtime);var origin=transform.Origin;if(lens.IsPositionBehind(origin))return new Settings();float depth=-(lens.GlobalTransform.AffineInverse()*origin).Z;if(depth<lens.Near)return new Settings();float ratio=Gizmo(owner).Call("display_transform").AsTransform2D().Scale.X;float length=lens.ProjectPosition(lens.UnprojectPosition(origin)+new Vector2(0,88/Math.Max(.001f,ratio)),depth).DistanceTo(origin);var axes=new[]{Vector3.Right,Vector3.Up,Vector3.Back};if(Mode(owner)=="scale"){var basis=Math.Abs(transform.Basis.Determinant())>.0000001?transform.Basis.Orthonormalized():Basis.Identity;axes=new[]{basis.X,basis.Y,basis.Z};}var rings=new GArray();var ends=new Vector2[3];for(int i=0;i<3;i++){ends[i]=project(owner,origin+axes[i]*length);var points=new Vector2[65];var u=axes[(i+1)%3];var v=axes[(i+2)%3];for(int j=0;j<65;j++)points[j]=project(owner,origin+(u*Mathf.Cos(Mathf.Tau*j/64)+v*Mathf.Sin(Mathf.Tau*j/64))*length*.8f);rings.Add(points);}return new Settings{["origin"]=origin,["center"]=project(owner,origin),["length"]=length,["axes"]=new Godot.Collections.Array<Vector3>(axes),["ends"]=ends,["rings"]=rings};
    }
    public Rect2 toolbar_rect(int index)=>new Rect2(10+index*78,10,74,27);
    public int handle_at(Node owner,Vector2 point,Settings data){if(data.Count==0)return -2;string mode=Mode(owner);var center=data["center"].AsVector2();if(mode!="rotate"&&point.DistanceTo(center)<10)return -1;float best=9;int chosen=-2;for(int i=0;i<3;i++){if(mode=="rotate"){var points=data["rings"].AsGodotArray()[i].AsVector2Array();for(int j=0;j<points.Length-1;j++){float distance=Geometry2D.GetClosestPointToSegment(point,points[j],points[j+1]).DistanceTo(point);if(distance<best){best=distance;chosen=i;}}}else{var end=data["ends"].AsVector2Array()[i];if(center.DistanceTo(end)<14)continue;float distance=Geometry2D.GetClosestPointToSegment(point,center.Lerp(end,.25f),end).DistanceTo(point);if(distance<best){best=distance;chosen=i;}}}return chosen;}
}
